<template>
  <div class="page"><TopBar /><main class="content"><template v-if="selected"><button class="back" @click="selected=null"><span class="material-symbols-outlined">arrow_forward</span> رجوع للقائمة</button><img :src="selected.img" class="hero"/><h2>{{ selected.name }}</h2><p><span class="material-symbols-outlined">location_on</span>{{ selected.address }}</p><button v-if="!isDealer" class="browse-branch" @click="$router.push('/store?branch=' + encodeURIComponent(selected.name))"><span class="material-symbols-outlined">storefront</span> تصفح منتجات الفرع</button><h3>التواصل</h3><a v-for="phone in selected.phones" :key="phone" :href="'https://wa.me/'+phone.replace(/^0/,'964')" target="_blank">{{ phone }} <span>واتساب</span></a></template><template v-else><h2>{{ title }}</h2><article v-for="item in items" :key="item.name" @click="selected=item"><img :src="item.img"/><div><h3>{{item.name}}</h3><p>{{item.address}}</p></div><span class="material-symbols-outlined">chevron_left</span></article></template></main><BottomNav /></div>
</template>
<script setup>
import{computed,ref}from'vue';import{useRoute}from'vue-router';import TopBar from'../components/TopBar.vue';import BottomNav from '../components/BottomNav.vue';const route=useRoute();const selected=ref(null);const branch=[{name:'الفرع الرئيسي - بغداد',address:'شارع الرشيد، وسط البلد، بغداد',img:'https://images.unsplash.com/photo-1497366216548-37526070297c?w=800&h=400&fit=crop',phones:['07701234567','07801234567']},{name:'فرع الأعظمية',address:'شارع حسين خليل، الأعظمية، بغداد',img:'https://images.unsplash.com/photo-1497366811353-6870744d04b2?w=800&h=400&fit=crop',phones:['07709876543']},{name:'فرع البصرة',address:'العشار، البصرة',img:'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&h=400&fit=crop',phones:['07801112233']}];const dealer=[{name:'وكالة الأمل للسيارات',address:'المنطقة الصناعية، بغداد',img:'https://images.unsplash.com/photo-1568605117036-5fe5e7bab0b7?w=800&h=400&fit=crop',phones:['07705556677']},{name:'وكالة النور للإلكترونيات',address:'شارع المتنبي، بغداد',img:'https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800&h=400&fit=crop',phones:['07704443322']}];const isDealer=computed(()=>route.path.includes('dealers'));const title=computed(()=>isDealer.value?'الوكلاء المعتمدون':'فروع الشركة');const items=computed(()=>isDealer.value?dealer:branch);if(route.query.branch)selected.value=items.value.find(item=>item.name===route.query.branch)||null
</script>
<style scoped>.page{height:100dvh;background:var(--bg);display:flex;flex-direction:column}.content{flex:1;overflow:auto;padding:16px}.content article{display:flex;align-items:center;gap:12px;padding:11px;margin:11px 0;background:var(--surface-container);border:1px solid var(--outline-variant);border-radius:15px;cursor:pointer}.content article img{width:74px;height:74px;border-radius:11px;object-fit:cover}.content article div{flex:1}.content h3,.content h2{color:var(--on-surface);font-size:15px}.content h2{font-size:19px}.content p{color:var(--on-surface-variant);font-size:12px;margin-top:5px;display:flex;gap:5px;align-items:center}.content p .material-symbols-outlined{color:var(--primary);font-size:17px}.hero{width:100%;height:190px;object-fit:cover;border-radius:15px;margin:10px 0}.back{display:flex;align-items:center;gap:4px;border:0;background:transparent;color:var(--primary);font:inherit;font-weight:700}.back .material-symbols-outlined{font-size:18px}.content>a{display:flex;justify-content:space-between;margin-top:10px;padding:12px;border-radius:12px;background:rgba(37,211,102,.1);border:1px solid rgba(37,211,102,.25);color:var(--on-surface);text-decoration:none;font-size:13px}.content>a span{color:#25d366}</style>
